// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _owner) public {
        // 1. restrict to admissible domain: admin (msg.sender of deployer = this) is allowed to call setOwner.
        //    The test contract itself deploys c, so it is admin. We prank from a different actor to exercise
        //    the onlyAdmin modifier if needed, but the property must hold for *any* call that succeeds.
        //    Succeeding calls come from admin = address(this). We fuzz _owner, call as admin, and check outcome.
        vm.prank(address(this));
        c.setOwner(_owner);
        // 3. single assert: the stored owner must equal the _owner argument.
        assertTrue(c.owner() == _owner);
    }
}

